private static readonly TaggedQueryCommandInterceptor _interceptor
    = new TaggedQueryCommandInterceptor();

protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    => optionsBuilder.AddInterceptors(_interceptor);

public class TaggedQueryCommandInterceptor : DbCommandInterceptor
{
    public override InterceptionResult<DbDataReader> ReaderExecuting(
        DbCommand command,
        CommandEventData eventData,
        InterceptionResult<DbDataReader> result)
    {
        ManipulateCommand(command);
        return result;
    }

    private static void ManipulateCommand(DbCommand command)
    {
        if (command.CommandText.StartsWith("-- Use hint: robust plan"))
        {
            command.CommandText += " OPTION (ROBUST PLAN)";
        }
    }
}

public override ValueTask<InterceptionResult<DbDataReader>> ReaderExecutingAsync(
    DbCommand command,
    CommandEventData eventData,
    InterceptionResult<DbDataReader> result,
    CancellationToken cancellationToken = default)
{
    if (command.CommandText.StartsWith("-- Get_Daily_Message"))
    {
        if (_message != null && DateTime.UtcNow < _queriedAt + TimeSpan.FromSeconds(10))
        {
            result = InterceptionResult<DbDataReader>.SuppressWithResult(
                new CachedDailyMessageDataReader(_id, _message));
        }
    }
    return new ValueTask<InterceptionResult<DbDataReader>>(result);
}
